/**
 * The ShadowPad mark: a launch triangle on an ember mirror plane, with its reflection
 * below in fading bands. Colors follow the theme through --logo-* tokens in globals.css.
 */
export const Logo = ({ size = 28, title }: { size?: number; title?: string }) => {
  const id = useId().replace(/:/g, "");
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" className="shrink-0" role={title ? "img" : undefined} aria-label={title} aria-hidden={title ? undefined : true}>
      <defs>
        <linearGradient id={`${id}t`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" style={{ stopColor: "var(--logo-hi)" }} />
          <stop offset="0.5" style={{ stopColor: "var(--logo-mid)" }} />
          <stop offset="1" style={{ stopColor: "var(--logo-lo)" }} />
        </linearGradient>
        <linearGradient id={`${id}b`} x1="0" y1="0" x2="1" y2="0">
          <stop offset="0" stopColor="#E8430A" />
          <stop offset="0.5" stopColor="#FF5B1F" />
          <stop offset="1" stopColor="#FF8A55" />
        </linearGradient>
        <clipPath id={`${id}r`}>
          <path d="M16 56H84L50 93Z" />
        </clipPath>
      </defs>
      <path d="M50 10L84 47H16Z" fill={`url(#${id}t)`} />
      <rect x="12" y="49.5" width="76" height="4" rx="2" fill={`url(#${id}b)`} />
      <g clipPath={`url(#${id}r)`} style={{ fill: "var(--logo-refl)" }}>
        <rect x="0" y="56" width="100" height="10" fillOpacity="0.55" />
        <rect x="0" y="69.5" width="100" height="9" fillOpacity="0.32" />
        <rect x="0" y="82" width="100" height="11" fillOpacity="0.16" />
      </g>
    </svg>
  );
};

